1	type Item = { type: string; enchantment?: number; cursed?: boolean; material?: string };
2	type Damage = { itemType: string; amount: number };
3	
4	const BASE_PREMIUMS: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: 25,
10	};
11	
12	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
13	const COMPONENT_PRICE = 25;
14	const BLOCK_SIZE = 3;
15	const BLOCK_PRICE = 60;
16	
17	const priceOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
18	
19	const componentPremium = (count: number): number =>
20	  count === BLOCK_SIZE ? BLOCK_PRICE : count * COMPONENT_PRICE;
21	
22	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
23	
24	const countByType = (items: Item[]): Record<string, number> => {
25	  const counts: Record<string, number> = {};
26	  for (const item of items) {
27	    counts[item.type] = (counts[item.type] ?? 0) + 1;
28	  }
29	  return counts;
30	};
31	
32	export const basePremium = (items: Item[]): number => {
33	  const mainItems = items.filter((item) => !isComponent(item));
34	  const componentCounts = countByType(items.filter(isComponent));
35	
36	  const mainTotal = mainItems.reduce((sum, item) => sum + priceOf(item), 0);
37	  const componentTotal = Object.values(componentCounts).reduce(
38	    (sum, count) => sum + componentPremium(count),
39	    0,
40	  );
41	
42	  return mainTotal + componentTotal;
43	};
44	
45	const PROCESSING_FEE = 5;
46	const FIRST_INSURANCE_RATE = 0.1;
47	const LOYALTY_RATE = 0.2;
48	const LOYALTY_MIN_YEARS = 2;
49	const HIGH_ENCHANTMENT_RATE = 0.3;
50	const HIGH_ENCHANTMENT_MIN = 5;
51	const CURSE_RATE = 0.5;
52	const FOLLOWUP_RATE = 0.15;
53	
54	const isHighlyEnchanted = (item: Item): boolean =>
55	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_MIN;
56	
57	const itemSurcharge = (item: Item): number => {
58	  const surchargeOf = (applies: boolean, rate: number): number =>
59	    applies ? priceOf(item) * rate : 0;
60	
61	  return (
62	    surchargeOf(item.cursed ?? false, CURSE_RATE) +
63	    surchargeOf(isHighlyEnchanted(item), HIGH_ENCHANTMENT_RATE)
64	  );
65	};
66	
67	export const premium = (
68	  items: Item[],
69	  opts: { yearsWithMHPCO: number; isFollowUp: boolean },
70	): number => {
71	  const base = basePremium(items);
72	  const adjustment = (applies: boolean, rate: number): number =>
73	    applies ? base * rate : 0;
74	
75	  const firstInsurance = adjustment(true, FIRST_INSURANCE_RATE);
76	  const loyalty = adjustment(
77	    opts.yearsWithMHPCO >= LOYALTY_MIN_YEARS,
78	    LOYALTY_RATE,
79	  );
80	  const followUp = adjustment(opts.isFollowUp, FOLLOWUP_RATE);
81	  const surcharges = items.reduce((sum, item) => sum + itemSurcharge(item), 0);
82	  return Math.ceil(
83	    base + firstInsurance - loyalty - followUp + surcharges + PROCESSING_FEE,
84	  );
85	};
86	
87	const DEDUCTIBLE = 100;
88	const HIGH_ENCHANTMENT_CLAIM_MIN = 8;
89	const HIGH_ENCHANTMENT_REIMBURSE_RATE = 0.5;
90	
91	const reimbursableAmount = (damage: Damage, item: Item | undefined): number =>
92	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_MIN
93	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSE_RATE
94	    : damage.amount;
95	
96	const reimbursementFor = (damage: Damage, policyItems: Item[]): number => {
97	  const item = policyItems.find((i) => i.type === damage.itemType);
98	  return reimbursableAmount(damage, item) - DEDUCTIBLE;
99	};
100	
101	export const payout = (damages: Damage[], policyItems: Item[]): number =>
102	  Math.floor(
103	    damages.reduce(
104	      (sum, damage) => sum + reimbursementFor(damage, policyItems),
105	      0,
106	    ),
107	  );
108	
109	const INSURANCE_VALUES: Record<string, number> = {
110	  sword: 1000,
111	  amulet: 600,
112	  staff: 800,
113	  potion: 400,
114	  rune: 250,
115	  moonstone: 250,
116	};
117	
118	const insuranceValueOf = (item: Item): number =>
119	  INSURANCE_VALUES[item.type] ?? 0;
120	
121	export const insuranceSum = (items: Item[]): number =>
122	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
123	
124	type QuoteStep = { op: "quote"; items: Item[] };
125	type ClaimStep = {
126	  op: "claim";
127	  policy: number;
128	  incident: { cause: string; damages: Damage[] };
129	};
130	type Step = QuoteStep | ClaimStep;
131	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
132	
133	type Policy = { items: Item[]; remainingCap: number };
134	
135	const CAP_MULTIPLIER = 2;
136	const KNOWN_TYPES = new Set(Object.keys(INSURANCE_VALUES));
137	
138	// --- Validation: reject impossible quotes/claims before pricing/settling ---
139	
140	const validateQuoteItems = (items: Item[]): void => {
141	  const unknown = items.find((item) => !KNOWN_TYPES.has(item.type));
142	  if (unknown) {
143	    throw new Error(`Unknown item type: ${unknown.type}`);
144	  }
145	};
146	
147	type ClaimCheck = (policy: Policy, damages: Damage[]) => void;
148	
149	const rejectDamagesNotInPolicy: ClaimCheck = (policy, damages) => {
150	  const orphan = damages.find(
151	    (damage) => !policy.items.some((item) => item.type === damage.itemType),
152	  );
153	  if (orphan) {
154	    throw new Error(`Item not in policy: ${orphan.itemType}`);
155	  }
156	};
157	
158	const rejectNegativeAmounts: ClaimCheck = (policy, damages) => {
159	  const negative = damages.find((damage) => damage.amount < 0);
160	  if (negative) {
161	    throw new Error(`Negative damage amount: ${negative.amount}`);
162	  }
163	};
164	
165	const CLAIM_CHECKS: ClaimCheck[] = [rejectDamagesNotInPolicy, rejectNegativeAmounts];
166	
167	const validateClaimDamages = (policy: Policy, damages: Damage[]): void => {
168	  CLAIM_CHECKS.forEach((check) => check(policy, damages));
169	};
170	
171	const openPolicy = (items: Item[]): Policy => ({
172	  items,
173	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
174	});
175	
176	const settleClaim = (policy: Policy, damages: Damage[]): number => {
177	  const desired = payout(damages, policy.items);
178	  const actual = Math.min(desired, policy.remainingCap);
179	  policy.remainingCap -= actual;
180	  return actual;
181	};
182	
183	export const runScenario = (scenario: Scenario): { results: unknown[] } => {
184	  const policies: Record<number, Policy> = {};
185	  let quoteCount = 0;
186	  const results: unknown[] = [];
187	
188	  scenario.steps.forEach((step, index) => {
189	    if (step.op === "quote") {
190	      validateQuoteItems(step.items);
191	      const opts = {
192	        yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
193	        isFollowUp: quoteCount > 0,
194	      };
195	      quoteCount += 1;
196	      policies[index] = openPolicy(step.items);
197	      results.push({ premium: premium(step.items, opts) });
198	    } else {
199	      const policy = policies[step.policy];
200	      validateClaimDamages(policy, step.incident.damages);
201	      const paidOut = settleClaim(policy, step.incident.damages);
202	      results.push({ payout: paidOut, remainingCap: policy.remainingCap });
203	    }
204	  });
205	
206	  return { results };
207	};
